#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_vector_find_value_found(void) {
    Vector* vec = NULL;
    int val = 42;
    int result;

    vec = helper_create_vector(10);
    TEST_ASSERT_NOT_NULL(vec);

    int values[] = {5, 10, 42, 15, 20};
    int count = sizeof(values) / sizeof(values[0]);
    int fill_result = helper_fill_vector(vec, values, count);
    TEST_ASSERT_EQUAL_INT(0, fill_result);

    result = vector_find(vec, val);
    TEST_ASSERT_EQUAL_INT(2, result);

    helper_cleanup_vector(vec);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_vector_find_value_found);
    return UNITY_END();
}

